    // 一键测速:对已登记端口跑固定 prompt 非流式生成,记 tok/s 并落盘 benchmarks.json
    webServer.register({
      kind: "exact",
      path: "/api/mm/bench",
      handler: actionHandler("POST", async (input) => {
        const r = await manager.bench(Number(input.port), {
          profile: input.profile || null,
